// nightly-sales-report.js
// Run once a day via cron, e.g: 0 2 * * *
const { MongoClient } = require('mongodb');

async function runNightlyReport() {
  const client = new MongoClient(process.env.MONGO_URI);
  await client.connect();
  const orders = client.db('shop').collection('orders');

  const yesterdayStart = new Date();
  yesterdayStart.setDate(yesterdayStart.getDate() - 1);
  yesterdayStart.setHours(0, 0, 0, 0);
  const yesterdayEnd = new Date(yesterdayStart);
  yesterdayEnd.setHours(23, 59, 59, 999);

  // Grab the whole accumulated chunk in one query.
  const summary = await orders.aggregate([
    { $match: { createdAt: { $gte: yesterdayStart, $lte: yesterdayEnd } } },
    { $group: { _id: '$category', total: { $sum: '$amount' }, count: { $sum: 1 } } },
  ]).toArray();

  await sendReportEmail(summary);
  await client.close();
}

runNightlyReport();

