// fraud-check-consumer.js
// Long running process, never exits on its own.
const { Kafka } = require('kafkajs');

const kafka = new Kafka({ clientId: 'fraud-checker', brokers: ['kafka:9092'] });
const consumer = kafka.consumer({ groupId: 'fraud-detection' });

async function scoreOrder(order) {
  let risk = 0;
  if (order.amount > 5000) risk += 40;
  if (order.recentFailedCharges >= 3) risk += 50;
  if (order.shippingCountry !== order.billingCountry) risk += 20;
  return risk;
}

async function run() {
  await consumer.connect();
  await consumer.subscribe({ topic: 'orders', fromBeginning: false });

  // This loop runs forever, processing one event at a time.
  await consumer.run({
    eachMessage: async ({ message }) => {
      const order = JSON.parse(message.value.toString());
      const risk = await scoreOrder(order);
      if (risk >= 70) {
        await flagOrderForReview(order.id, risk);
      }
    },
  });
}

run();

